/**
 * glTF has no lightmap slot, so the lightmap ships in the emissive
 * slot on UV1. Call this once after loading.
 */
export function promoteEmissiveToLightmap(
  mat: THREE.MeshStandardMaterial
): void {
  if (!mat.emissiveMap) return;
  mat.lightMap = mat.emissiveMap;
  mat.lightMap.channel = 1;
  mat.emissiveMap = null;
  mat.emissive.setRGB(0, 0, 0);
  mat.needsUpdate = true;
}
